using System.Linq.Expressions;using Microsoft.EntityFrameworkCore;using Npgsql;using ZosyalMedya.BuildingBlocks.Application.Persistence;using ZosyalMedya.Modules.Reactions.Application.Ports;using ZosyalMedya.Modules.Reactions.Domain.Reactions;
namespace ZosyalMedya.Modules.Reactions.Infrastructure.Persistence.PostgreSql;
public sealed class PostgreSqlReactionRepository(ReactionsDbContext db):IReactionRepository
{public async Task<Reaction?>SelectAsync(Expression<Func<Reaction,bool>>predicate,CancellationToken cancellationToken=default){var x=await db.Reactions.AsNoTracking().Where(predicate).OrderBy(x=>x.Id).Take(2).ToListAsync(cancellationToken);return x.SingleOrDefault();}public async Task<IReadOnlyList<Reaction>>ListByFilterAsync(Expression<Func<Reaction,bool>>predicate,QueryOptions<Reaction>?options=null,CancellationToken cancellationToken=default){options??=new();return await db.Reactions.AsNoTracking().Where(predicate).OrderBy(x=>x.Id).Take(options.BoundedLimit).ToListAsync(cancellationToken);}public async Task<ReactionId>CreateAsync(Reaction entity,CancellationToken cancellationToken=default){try{db.Add(entity);await db.SaveChangesAsync(cancellationToken);db.Entry(entity).State=EntityState.Detached;return entity.Id;}catch(DbUpdateException ex)when(ex.InnerException is PostgresException{SqlState:PostgresErrorCodes.UniqueViolation}){db.ChangeTracker.Clear();throw new PersistenceConflictException("reactions.unique_conflict","Bir aktör içerik için yalnız bir tepki kaydı oluşturabilir.",ex);}}public async Task<bool>UpdateAsync(Expression<Func<Reaction,bool>>predicate,Reaction replacement,long?expectedVersion=null,CancellationToken cancellationToken=default){var q=db.Reactions.Where(predicate);if(expectedVersion.HasValue)q=q.Where(x=>x.Version==expectedVersion);var current=await q.SingleOrDefaultAsync(cancellationToken);if(current is null)return false;db.Entry(current).CurrentValues.SetValues(replacement);try{return await db.SaveChangesAsync(cancellationToken)==1;}catch(DbUpdateConcurrencyException){return false;}finally{db.ChangeTracker.Clear();}}public async Task<long>DeleteByFilterAsync(Expression<Func<Reaction,bool>>predicate,CancellationToken cancellationToken=default)=>await db.Reactions.Where(predicate).ExecuteDeleteAsync(cancellationToken);public async Task<IReadOnlyDictionary<ReactionKind,long>>CountActiveByContentAsync(ReactedContentId contentId,CancellationToken cancellationToken=default)=>await db.Reactions.AsNoTracking().Where(x=>x.ContentId==contentId&&x.IsActive).GroupBy(x=>x.Kind).ToDictionaryAsync(x=>x.Key,x=>x.LongCount(),cancellationToken);}
